        for f in files:
            if f.startswith('.') and not f.startswith('..'):
                os.chmod(os.path.join(root, f), 0o777)
                os.remove(os.path.join(root, f))
        for d in dirs:
            remove_hidden_files(os.path.join(root, d))

def backup_and_extract(tar_ball, dest):
    shutil.move(tar_ball, dest)
    extract_tarball(dest)
